    wire [31:0] am_val;
    wire       am_any;

    `define F(name) ir[O_``name +: W_``name]
    ot_hdc_dyn_ttiles #(.W(W),.G(G),.NW(NW)) u_dyn_tiles_zero (
        .pos(pos_r),.split_log2(4'd0),.rounds(dyn_tiles_zero),.invalid_split());
    ot_hdc_dyn_ttiles #(.W(W),.G(G),.NW(NW)) u_dyn_tiles_split (
        .pos(pos_r),.split_log2(`F(ME_SPLIT)),.rounds(dyn_tiles_split),
        .invalid_split(dyn_tiles_invalid));
    wire dyn_tiles_bad_instruction = load && `F(ME_D_TILES) == 3'd6 && dyn_tiles_invalid;

    // decoded, DYN-adjusted fields
    reg [1:0]    d_unit;
    reg          d_barrier;
    reg [NW-1:0] me_nout, me_tiles, me_k;
    reg          me_wsrc, me_round, me_oen, me_amax, me_mmode, d_chase, d_wait_me, d_wait_su, me_rmax, me_amc;
    reg [NW-1:0] me_row0;
    reg [AW-1:0] me_mbase;
    reg [15:0]   d_chase_n;
    reg [AW-1:0] me_wbase, me_ts, me_ks, me_js, me_xbase, me_obase, me_xks, me_xjs, me_ots, me_ojs;
    reg [2:0]    me_jsh;
    reg [3:0]    me_split;
    reg [AW-1:0] me_xcs, me_wcs;
    reg [NW-1:0] su_nout, su_nin;
    reg          a_src, b_src, c_src, mc;
    reg [AW-1:0] a_base, a_so, a_si, b_base, b_so, b_si, c_base, c_so, c_si;
    reg [AW-1:0] d_base, d_so, d_si, r_base, r_so;
    reg [1:0]    ma, mb, dst, red;
    reg [2:0]    sfu;
    reg          redsq, md;
    reg [2:0]    ad;
    reg [31:0]   imm1, imm2;

    wire [15:0] su_progress, me_progress, su_rows;
    reg          d_chase_rows;
    reg          me_kindk;
    wire me_en;
    wire unit_ready = (d_unit == 2'd1) ? (me_ready && me_en) :
                      (su_ready && (!KV_VEC_WRITE_BRIDGE || (su_idle && kv_write_drained)));
    //: KV_HBM: a KV op waits for the streamer; never on the cycle its
    //: descriptor is announced, when kv_ok may still describe the previous op.
    wire kv_gate = (KV_HBM == 0) || !(d_unit == 2'd1 && me_wsrc) || (kv_ok && !kvd_v);
    wire w_gate = (W_HBM == 0) || ((d_unit == 2'd1) ?
                  (me_wsrc || (w_ok && !wd_v)) : (!a_src || emb_ok));
    //: the units' idle and progress are registered and cleared on the edge
    //: that accepts an op, so a go needs no guard term here
    wire drained = me_idle && su_idle && (!KV_VEC_WRITE_BRIDGE || kv_write_drained);
    assign kv_write_flush = su_idle && !(|kv_we);
    //: A chasing op waits only until the OTHER unit's latest op has made
    //: chase_n progress.
    // redesign-qwen two controllers: own / other unit, the other side's snapshot, the dependency hold
    reg  [XW-1:0] o_cnt;                       // other-unit instructions passed so far
    wire own = (d_unit == OWN[1:0]);
    wire oth = (d_unit != 2'd0) && !own;
    wire [XW-1:0] o_dif = x_oacc - o_cnt;
    wire osync = (o_dif == {XW{1'b0}});        // the other unit accepted exactly its earlier ops
    wire opast = !osync && !o_dif[XW-1];       // ... and the one at NEXT
    wire own_idle = (OWN == 1) ? me_idle : su_idle;
    wire o_drained = osync && x_oidle;
    wire x_drained = own_idle && o_drained && (!KV_VEC_WRITE_BRIDGE || kv_write_drained);
    wire [15:0] x_och = (OWN == 1) ? (d_chase_rows ? x_orows : x_oprog) : x_oprog;
    wire chased = osync && (x_och >= d_chase_n);
    wire wait_o = (OWN == 1) ? d_wait_su : d_wait_me;
    wire wait_u = (OWN == 1) ? d_wait_me : d_wait_su;
    wire xdep_ok = (XMUT == 1 && OWN == 1) ? 1'b1 :
                   (d_barrier ? x_drained : ((!d_chase || chased) && (!wait_u || own_idle) && (!wait_o || o_drained)));
    wire odep = (XMUT == 2) ? 1'b0 : (d_barrier || d_chase || ((OWN == 1) ? d_wait_me : d_wait_su));
    wire skip = (st == S_RUN) && nx_v && oth && (!odep || opast);
    //: issue NEXT this cycle; the unit latches its fields on this edge
    wire issue = (st == S_RUN) && nx_v && own && xdep_ok
                 && unit_ready && kv_gate && w_gate;
    assign me_go = issue && (d_unit == 2'd1);
    assign su_go = issue && (d_unit == 2'd2);
    wire fin = (st == S_RUN) && nx_v && (d_unit == 2'd0) && x_drained && ((OWN == 1) || x_ofin);
    reg fin_seen;                              // this controller reached END in this run
    always @(posedge clk or negedge rst_n)
        if (!rst_n) fin_seen <= 1'b0;
        else if (start && st == S_IDLE) fin_seen <= 1'b0;
        else if (fin) fin_seen <= 1'b1;
    assign o_fin = fin_seen;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) o_cnt <= {XW{1'b0}};
        else if (skip) o_cnt <= o_cnt + 1'b1;
    //: decode the FIFO head into NEXT when NEXT is empty or issuing
    wire load = (st == S_RUN) && ((FQ_HEAD != 0) ? hq_v : (fq_n != 0)) && (!nx_v || issue || skip);
    // FQ_HEAD: the FIFO pops into hq when hq is empty or being loaded into NEXT
    wire hq_fill = (FQ_HEAD != 0) && (st == S_RUN) && (fq_n != 0) && (!hq_v || load);
    wire fq_pop = (FQ_HEAD != 0) ? hq_fill : load;
    wire push = (st == S_RUN) && pend1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= S_IDLE; pc <= 0; fpc <= 0; done <= 1'b0; prog_re <= 1'b0; pend1 <= 1'b0;
            fq_rd <= 0; fq_wr <= 0; fq_n <= 0; nx_v <= 1'b0; hq_v <= 1'b0;
            cycles <= 0; next_token <= 0;
        end else begin
            if (st != S_IDLE) cycles <= cycles + 1;
            pend1 <= prog_re && (st != S_IDLE);
            prog_re <= 1'b0;
            case (st)
                S_IDLE: if (start) begin
                    tok_r <= token; pos_r <= pos; pc <= 0; fpc <= 0; done <= 1'b0; cycles <= 0;
                    fq_rd <= 0; fq_wr <= 0; fq_n <= 0; nx_v <= 1'b0; pend1 <= 1'b0; hq_v <= 1'b0;
                    st <= S_DYN;
                end
                S_DYN: st <= S_RUN;
                S_RUN: begin
                    // fetch: one word a cycle while fewer than NFQ are held or in flight
                    if ({1'b0, fq_n} + ((FQ_HEAD != 0) ? hq_v : 1'b0) + prog_re + pend1 < NFQ) begin
                        prog_re <= 1'b1; prog_addr <= fpc; fpc <= fpc + 1'b1;
                    end
                    if (push) begin fq[fq_wr] <= prog_q; fq_wr <= fq_wr + 1'b1; end
                    if (fq_pop) fq_rd <= fq_rd + 1'b1;
                    fq_n <= fq_n + (push ? 3'd1 : 3'd0) - (fq_pop ? 3'd1 : 3'd0);
                    if (hq_fill) begin hq <= fq[fq_rd]; hq_v <= 1'b1; end
                    else if (load && FQ_HEAD != 0) hq_v <= 1'b0;
                    if (issue || skip) pc <= pc + 1'b1;
                    if (load) nx_v <= 1'b1;
                    else if (issue || skip) nx_v <= 1'b0;
                    if (fin) begin
                        done <= 1'b1; next_token <= (OWN == 2) ? x_fidx : fin_idx; next_val <= (OWN == 2) ? x_fval : fin_val; st <= S_IDLE; nx_v <= 1'b0;
                        prog_re <= 1'b0;
                    end
                end
                default: st <= S_IDLE;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin kvd_v <= 1'b0; wd_v <= 1'b0; end
        else begin
            kvd_v <= load && ir[O_UNIT +: W_UNIT] == 2'd1 && ir[O_ME_WSRC];
            wd_v <= (W_HBM != 0) && load && ir[O_UNIT +: W_UNIT] == 2'd1 && !ir[O_ME_WSRC];
        end
    end
    assign kvd_wbase = me_wbase; assign kvd_ts = me_ts; assign kvd_ks = me_ks; assign kvd_js = me_js;
    assign kvd_wcs = me_wcs; assign kvd_split = me_split;
    assign kvd_jsh = me_jsh; assign kvd_tiles = me_tiles; assign kvd_k = me_k; assign kvd_nout = me_nout;
    assign kvd_kindk = me_kindk; assign kvd_pos = pos_r;
    assign wd_wbase = me_wbase; assign wd_tiles = me_tiles; assign wd_k = me_k;
    assign wd_sbase = (INT8_WEIGHT != 0 && INT8_SCALE_WCS_BASE != 0) ? me_wcs : me_wbase;
    assign wd_nout = me_nout; // useful BF16 row scales to preload from HBM

    // The chunked weight program divides lm_head into bounded streams. Fold
    // each completed chunk's argmax before issuing the next one. The final
    // chunk remains in u_me and is included exactly once at END.
    function automatic [31:0] okey(input [31:0] v);
        okey = v[31] ? ~v : {1'b1, v[30:0]};
    endfunction
    reg run_any;
    reg [31:0] run_key,run_val;
    reg [NW-1:0] run_idx,last_row0;
    wire am_wins = am_any && (!run_any || okey(am_val) > run_key);
    wire [NW-1:0] fin_idx = am_wins ? am_idx + last_row0 : run_idx;
    wire [31:0] fin_val = am_wins ? am_val : run_val;
    assign o_fidx = fin_idx; assign o_fval = fin_val;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin run_any<=1'b0; last_row0<=0; end
        else if (start && st==S_IDLE) begin run_any<=1'b0; last_row0<=0; end
        else if (me_go && me_amax) begin
            last_row0<=me_row0;
            if (!me_amc) run_any<=1'b0;
            else if (am_wins) begin
                run_any<=1'b1; run_key<=okey(am_val);
                run_idx<=am_idx+last_row0; run_val<=am_val;
            end
        end
    end

    // DYN offsets derived once per token.
    always @(posedge clk) if (st == S_DYN) begin
        dyn[0] <= 0;
        dyn[1] <= tok_r * HID;
        dyn[2] <= pos_r * HALF;
        dyn[3] <= (pos_r >> LW) * (HD * W) + (pos_r & (W - 1));
        dyn[4] <= pos_r * HD;
        dyn[5] <= pos_r + 1;
        dyn[6] <= dyn_tiles_zero;                 // rounds of G position tiles (split 0)
        dyn[7] <= 0;
    end

    // Decode: every base and count may add one DYN value.
    always @(posedge clk) if (load) begin
        d_unit <= `F(UNIT); d_barrier <= `F(BARRIER);
        me_nout <= `F(ME_NOUT) + dyn[`F(ME_D_NOUT)];
        //: DYN_TTILES counts exact rounds of G/S position tiles (S = 2^split)
        me_tiles <= `F(ME_TILES) + ((`F(ME_D_TILES) == 3'd6) ? dyn_tiles_split
                                                               : dyn[`F(ME_D_TILES)]);
        me_k <= `F(ME_K) + dyn[`F(ME_D_K)];
        me_kindk <= (`F(ME_D_TILES) == 3'd6);        // DYN_TTILES: rounds of position tiles
        me_wsrc <= `F(ME_WSRC); me_round <= `F(ME_ROUND); me_oen <= `F(ME_OEN); me_amax <= `F(ME_AMAX);
        me_amc <= `F(ME_AMC);
        me_row0 <= `F(ME_ROW0) |
                   ((QWEN_FULLSHAPE != 0) ?
                    ({{(NW-2){1'b0}}, ir[O_ME_ROW0+W_ME_ROW0+W_ME_AMC +: 2]} << 16) : '0);
        me_wbase <= `F(ME_WBASE) + dyn[`F(ME_D_WBASE)];
        me_ts <= `F(ME_TS); me_ks <= `F(ME_KS); me_js <= `F(ME_JS);
        me_xbase <= `F(ME_XBASE) + dyn[`F(ME_D_XBASE)];
        me_obase <= `F(ME_OBASE) + dyn[`F(ME_D_OBASE)];
        me_xks <= `F(ME_XKS); me_xjs <= `F(ME_XJS); me_jsh <= `F(ME_JSH);
        me_ots <= `F(ME_OTS); me_ojs <= `F(ME_OJS); me_mmode <= `F(ME_MMODE);
        d_chase <= `F(CHASE); d_chase_n <= `F(CHASE_N); d_wait_me <= `F(WAIT_ME); d_wait_su <= `F(WAIT_SU);
        d_chase_rows <= `F(CHASE_ROWS);
        me_split <= `F(ME_SPLIT); me_xcs <= `F(ME_XCS); me_wcs <= `F(ME_WCS);
        me_rmax <= `F(ME_RMAX); me_mbase <= `F(ME_MBASE);
        su_nout <= `F(SU_NOUT);
        su_nin <= `F(SU_NIN) + dyn[`F(SU_D_NIN)];
        a_src <= `F(A_SRC); a_base <= `F(A_BASE) + dyn[`F(A_D)]; a_so <= `F(A_SO); a_si <= `F(A_SI);
        b_src <= `F(B_SRC); b_base <= `F(B_BASE) + dyn[`F(B_D)]; b_so <= `F(B_SO); b_si <= `F(B_SI);
        c_src <= `F(C_SRC); c_base <= `F(C_BASE) + dyn[`F(C_D)]; c_so <= `F(C_SO); c_si <= `F(C_SI);
        ma <= `F(MA); mb <= `F(MB); ad <= `F(AD); sfu <= `F(SFU); mc <= `F(MC); md <= `F(MD);
        dst <= `F(DST); d_base <= `F(D_BASE) + dyn[`F(D_D)]; d_so <= `F(D_SO); d_si <= `F(D_SI);
        red <= `F(RED); redsq <= `F(RED_SQ); r_base <= `F(R_BASE); r_so <= `F(R_SO);
        imm1 <= `F(IMM1); imm2 <= `F(IMM2);
    end
    `undef F

    // -- units ----------------------------------------------------------------------
    wire me_wrom_re, su_wrom_re;
    wire [AW-1:0] me_wrom_addr, su_wrom_addr;
    wire [SW-1:0] su_va_re;
    wire [SW*AW-1:0] su_va_addr;
    wire [SW*32-1:0] su_va_q;
    reg embed_active, embed_scale_pending;
    reg [15:0] embed_scale_hold;
    reg [SW-1:0] embed_sel;
    reg [SW*$clog2(EMB_CODE_LANES)-1:0] embed_lanes;
    wire [SW-1:0] embed_faults;
    assign embed_scale_re = (INT8_EMBED != 0) && start && st == S_IDLE;
    assign embed_scale_addr = token;
    assign embed_code_re = (INT8_EMBED != 0) && (|(su_va_re & {SW{embed_active}}));
    // The stream's element address is AW bits; token*HID wraps for vocab
    // rows >= 2^(AW-log2(HID)). Recover the in-row offset from those low
    // bits, then form the code-word address from the full NW-bit token.
    assign embed_code_addr = (QWEN_FULLSHAPE != 0) ?
        ((tok_r * (HID / EMB_CODE_LANES)) +
         (((su_va_addr[0 +: AW] - EMB_ADDR_BASE) & (HID - 1)) /
          EMB_CODE_LANES)) :
        ((su_va_addr[0 +: AW] - EMB_ADDR_BASE) >> $clog2(EMB_CODE_LANES));
    assign va_re = su_va_re & ~({SW{(INT8_EMBED != 0) && embed_active}});
    assign va_addr = su_va_addr;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            embed_active <= 1'b0;
            embed_scale_pending <= 1'b0;
            embed_sel <= 0;
        end else begin
            if (su_go) embed_active <= (INT8_EMBED != 0) && a_src;
            embed_scale_pending <= embed_scale_re;
            embed_sel <= su_va_re & {SW{(INT8_EMBED != 0) && embed_active}};
        end
    end
    always @(posedge clk) begin
        if (embed_scale_pending) embed_scale_hold <= embed_scale_q;
    end
    genvar el;
    generate if (INT8_EMBED != 0) begin : g_int8_embed
    for (el = 0; el < SW; el = el + 1) begin : g_embed_decode
        localparam integer ELI = $clog2(EMB_CODE_LANES);
        always @(posedge clk) embed_lanes[el*ELI +: ELI] <= su_va_addr[el*AW +: ELI];
        wire [31:0] decoded;
        wire bad;
        ot_hdc_qwen_int8_embed_decode u_decode (
            .code(embed_code_q[8*embed_lanes[el*ELI +: ELI] +: 8]),
            .scale(embed_scale_hold), .value(decoded), .fault(bad));
        assign su_va_q[el*32 +: 32] = embed_sel[el] ? decoded : va_q[el*32 +: 32];
        assign embed_faults[el] = embed_sel[el] && bad;
    end
    end else begin : g_plain_embed
        assign su_va_q = va_q;
        assign embed_faults = 0;
    end endgenerate
    // -- engine clock enable (ME_STALL) ------------------------------------------
    //: rst_n forces the enable so the gated registers see reset edges (see
    //: ot_hdc_cg).  The enable is combinational from the supply's view of the
    //: engine's registered requests; it never depends on me_go.
    wire me_wake = (st == S_RUN) && nx_v && (d_unit == 2'd1);
    assign me_en = !rst_n || (((ME_STALL == 0) || me_mem_ok) &&
                              ((ME_IDLE_GATE == 0) || !me_idle || me_wake));
    assign me_clk_en = me_en;
    wire me_clk;
    generate if (ME_STALL != 0 || ME_IDLE_GATE != 0) begin : g_me_cg
        ot_hdc_cg u_me_cg (.clk(clk), .en(me_en), .gclk(me_clk));
    end else begin : g_me_clk
        assign me_clk = clk;
    end endgenerate
    wire [(G >> SMIN)-1:0] me_o_we;
    wire         me_mx_we;
    //: a held engine keeps its write strobes high; write once per engine edge
    assign vw_me_we = me_o_we & {(G >> SMIN){me_en}};
    assign vw_mx_we = me_mx_we & me_en;
    // ---- matrix engine spine (die master qfd_sp_tree_top): ports ----
    assign po_me_clk = me_clk;
    assign po_me_go = me_go;
    assign me_ready = pi_me_ready;
    assign me_idle = pi_me_idle;
    assign po_me_i_nout = me_nout;
    assign po_me_i_tiles = me_tiles;
    assign po_me_i_k = me_k;
    assign po_me_i_wsrc = me_wsrc;
    assign po_me_i_wbase = me_wbase;
    assign po_me_i_ts = me_ts;
    assign po_me_i_ks = me_ks;
    assign po_me_i_js = me_js;
    assign po_me_i_xbase = me_xbase;
    assign po_me_i_xks = me_xks;
    assign po_me_i_xjs = me_xjs;
    assign po_me_i_xcs = me_xcs;
    assign po_me_i_jsh = me_jsh;
    assign po_me_i_split = me_split;
    assign po_me_i_wcs = me_wcs;
    assign po_me_i_round = me_round;
    assign po_me_i_obase = me_obase;
    assign po_me_i_ots = me_ots;
    assign po_me_i_ojs = me_ojs;
    assign po_me_i_mmode = me_mmode;
    assign po_me_i_oen = me_oen;
    assign po_me_i_amax = me_amax;
    assign po_me_i_rmax = me_rmax;
    assign po_me_i_mbase = me_mbase;
    assign me_mx_we = pi_me_mx_we;
    assign vw_mx_addr = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vw_mx_mask = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vw_mx_data = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign me_wrom_re = pi_me_wrom_re;
    assign me_wrom_addr = pi_me_wrom_addr;
    assign scale_re = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign scale_gre = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign scale_addr = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign kv_re = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vx_re = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vx_addr = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign tgo = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign tb = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign xl_d = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign me_ov = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign me_o_we = pi_me_o_we;
    assign vw_me_addr = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vw_me_mask = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign vw_me_data = '0;   // driven by the spine in ot_qwen_rom_core_part
    assign am_idx = pi_me_am_idx;
    assign am_val = pi_me_am_val;
    assign am_any = pi_me_am_any;
    assign me_progress = pi_me_progress;
    assign me_fault = pi_me_fault;

    wire       su_active;             // observation (test benches)
    wire [7:0] su_inflight;
    // ---- vector stream unit (die master qfd_sp_su64_sfu): ports (SU_VEC = 1 only) ----
    assign po_su_asrc_raw = a_src;   // split-exact: the embedding selector travels with the go
    assign su_active = pi_su_rt_active;
    assign su_inflight = pi_su_rt_inflight;
    assign po_su_go = su_go;
    assign su_ready = pi_su_ready;
    assign su_idle = pi_su_idle;
    assign po_su_i_nout = su_nout;
    assign po_su_i_nin = su_nin;
    assign po_su_i_asrc = (INT8_EMBED != 0) ? 1'b0 : a_src;
    assign po_su_i_abase = a_base;
    assign po_su_i_aso = a_so;
    assign po_su_i_asi = a_si;
    assign po_su_i_bsrc = b_src;
    assign po_su_i_bbase = b_base;
    assign po_su_i_bso = b_so;
    assign po_su_i_bsi = b_si;
    assign po_su_i_csrc = c_src;
    assign po_su_i_cbase = c_base;
    assign po_su_i_cso = c_so;
    assign po_su_i_csi = c_si;
    assign po_su_i_ma = ma;
    assign po_su_i_mb = mb;
    assign po_su_i_ad = ad;
    assign po_su_i_sfu = sfu;
    assign po_su_i_mc = mc;
    assign po_su_i_md = md;
    assign po_su_i_dst = dst;
    assign po_su_i_dbase = d_base;
    assign po_su_i_dso = d_so;
    assign po_su_i_dsi = d_si;
    assign po_su_i_red = red;
    assign po_su_i_redsq = redsq;
    assign po_su_i_rbase = r_base;
    assign po_su_i_rso = r_so;
